CREATE TABLE standings ( id SERIAL PRIMARY KEY, position INT NOT NULL, team_name TEXT NOT NULL, team_logo TEXT, played INT NOT NULL, won INT NOT NULL, draw INT NOT NULL, lost INT NOT NULL, points INT NOT NULL, goals_for INT NOT NULL, goals_against INT NOT NULL, updated_at TIMESTAMPTZ DEFAULT NOW() ); CREATE TABLE calendar_matches ( id SERIAL PRIMARY KEY, api_id INT UNIQUE NOT NULL, competition TEXT NOT NULL, home_team TEXT NOT NULL, home_logo TEXT, away_team TEXT NOT NULL, away_logo TEXT, match_date TIMESTAMPTZ NOT NULL, status TEXT NOT NULL, score_home INT, score_away INT, updated_at TIMESTAMPTZ DEFAULT NOW() ); ALTER TABLE standings ENABLE ROW LEVEL SECURITY; CREATE POLICY "Public read access on standings" ON standings FOR SELECT USING (true); ALTER TABLE calendar_matches ENABLE ROW LEVEL SECURITY; CREATE POLICY "Public read access on calendar_matches" ON calendar_matches FOR SELECT USING (true);